#[derive(Clone, Copy, Debug)]
enum Arena3Step {
    Start,
    OnInit,
    OnEnable,
    OnDisable,
}

fn arena_3_run(ctx: &Ctx, mut step: Arena3Step, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            Arena3Step::Start => {
                step = Arena3Step::OnInit;
                continue 'machine;
            }
            Arena3Step::OnInit => {
                ctx.call(Function::DisableNpc, vec![Val::from("Arena#3")])?;
                return Err(Stop::End);
            }
            Arena3Step::OnEnable => {
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("job_sage"),
                        Val::from(107),
                        Val::from(106),
                        Val::from("Absent 3 times"),
                        Val::from(1185),
                        Val::from(1),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("job_sage"),
                        Val::from(124),
                        Val::from(106),
                        Val::from("Being Late 5 times"),
                        Val::from(1185),
                        Val::from(1),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("job_sage"),
                        Val::from(107),
                        Val::from(89),
                        Val::from("Cheating 2 times"),
                        Val::from(1185),
                        Val::from(1),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("job_sage"),
                        Val::from(124),
                        Val::from(89),
                        Val::from("Cheating 4 times"),
                        Val::from(1185),
                        Val::from(1),
                    ],
                )?;
                return Err(Stop::End);
            }
            Arena3Step::OnDisable => {
                ctx.call(Function::KillMonster, vec![Val::from("job_sage"), Val::from("All")])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn arena_3(ctx: &Ctx) -> Script {
    arena_3_run(ctx, Arena3Step::Start, Vec::new()).map(|_| ())
}

pub fn arena_3_oninit(ctx: &Ctx) -> Script {
    arena_3_run(ctx, Arena3Step::OnInit, Vec::new()).map(|_| ())
}

